static int gp_rpc_execute(struct gp_call_ctx *gpcall, uint32_t proc, /* <=== gp_rpc_execute */ 
                          union gp_rpc_arg *arg, union gp_rpc_res *res)
{
    GPDEBUG("gp_rpc_execute: executing %d (%s) for service \"%s\", euid: %d,"
            "socket: %s\n", proc, gp_rpc_procname(proc),
            gpcall->service->name, gp_conn_get_uid(gpcall->connection),
            gpcall->service->socket);

    return gp_xdr_set[proc].exec_fn(gpcall, arg, res);
}

static const char *gp_rpc_procname(uint32_t proc) /* <=== gp_rpc_procname */ 
{
    if (proc > GSSX_PROC_MAX) {
        return NULL;
    }

    return gp_xdr_set[proc].proc_name;
}

static int gp_rpc_return_buffer(XDR *xdr_reply_ctx, char *reply_buffer, /* <=== gp_rpc_return_buffer */ 
                                uint8_t **outbuf, size_t *outlen)
{
    unsigned int length;
    uint8_t *buffer;

    length = xdr_getpos(xdr_reply_ctx);

    buffer = malloc(length);
    if (!buffer) {
        return ENOMEM;
    }
    memcpy(buffer, reply_buffer, length);

    *outbuf = buffer;
    *outlen = length;
    return 0;
}

void gp_debug_time_printf(const char *format, ...) /* <=== gp_debug_time_printf */ 
{
    va_list varargs;

    fprintf(stderr, "%s%s", gp_debug_conn_id(), gp_debug_timestamp());

    va_start(varargs, format);
    vfprintf(stderr, format, varargs);
    va_end(varargs);
}

