bool gp_conn_check_selinux(struct gp_conn *conn, SELINUX_CTX ctx) /* <=== gp_conn_check_selinux */ 
{
    if (ctx == NULL) {
        return true;
    }

    if (!(conn->creds.type & CRED_TYPE_SELINUX) ||
         (conn->selinux_ctx == NULL)) {
        return false;
    }

    return gp_selinux_ctx_equal(ctx, conn->selinux_ctx);
}

